//! SkyFrame `resolve` and `intersect`, which work on great circles, checked
//! against the C library.
//!
//! `sky_geometry_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/sky_geometry_probe.c`, which calls `astResolve` and
//! `astIntersect` on a default SkyFrame and on one with its axes swapped,
//! including bad inputs and the degenerate cases C reports as bad.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "sky_geometry_oracle/cases.rs"]
mod cases;

use ast_core::frames::{Frame, SkyFrame};

fn sky(permuted: bool) -> SkyFrame {
    let mut f = SkyFrame::unset_system();
    if permuted {
        f.perm_axes(&[2, 1]).unwrap();
    }
    f
}

#[test]
fn resolve_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(permuted, p1, p2, p3, p4, d1, d2) in cases::RESOLVE_CASES {
        let (g4, g1, g2) = sky(permuted).resolve(&p1, &p2, &p3).unwrap();
        if g4 != p4 || g1 != d1 || g2 != d2 {
            failures.push(format!(
                "permuted {permuted} {p1:?} {p2:?} {p3:?}: got {g4:?} {g1} {g2}, C gives {p4:?} {d1} {d2}"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn intersect_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(permuted, a1, a2, b1, b2, cross) in cases::INTERSECT_CASES {
        let got = sky(permuted).intersect(&a1, &a2, &b1, &b2).unwrap();
        if got != cross {
            failures.push(format!(
                "permuted {permuted} {a1:?} {a2:?} {b1:?} {b2:?}: got {got:?}, C gives {cross:?}"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// The CmpFrame of `kind` 0, (SkyFrame, SpecFrame), or 1, (Frame(1),
/// SkyFrame), with axes 1 and 3 swapped when `permuted`.
fn cmp(kind: usize, permuted: bool) -> ast_core::frames::CmpFrame {
    use ast_core::frames::{BasicFrameBuilder, CmpFrame, SpecFrame};
    let mut f = if kind == 0 {
        CmpFrame::new(
            Box::new(SkyFrame::unset_system()),
            Box::new(SpecFrame::unset_system()),
        )
    } else {
        CmpFrame::new(
            Box::new(BasicFrameBuilder::new(1).build().unwrap()),
            Box::new(SkyFrame::unset_system()),
        )
    };
    if permuted {
        f.perm_axes(&[3, 2, 1]).unwrap();
    }
    f
}

#[test]
fn cmp_frame_resolve_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(kind, permuted, p1, p2, p3, p4, d1, d2) in cases::CMP_RESOLVE_CASES {
        let (g4, g1, g2) = cmp(kind, permuted).resolve(&p1, &p2, &p3).unwrap();
        if g4 != p4 || g1 != d1 || g2 != d2 {
            failures.push(format!(
                "kind {kind} permuted {permuted} {p1:?} {p2:?} {p3:?}: got {g4:?} {g1} {g2}, C gives {p4:?} {d1} {d2}"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn cmp_frame_resolve_points_matches_the_c_library() {
    use ast_core::coords::PointSet;
    let mut failures = Vec::new();
    for &(kind, permuted, p1, p2, pts, d1s, d2s) in cases::CMP_RESOLVE_POINTS_CASES {
        let input = PointSet::from_rows(pts);
        let out = cmp(kind, permuted)
            .resolve_points(&p1, &p2, &input)
            .unwrap();
        for i in 0..3 {
            let (g1, g2) = (out.point(i)[0], out.point(i)[1]);
            if g1 != d1s[i] || g2 != d2s[i] {
                failures.push(format!(
                    "kind {kind} permuted {permuted} point {i}: got {g1} {g2}, C gives {} {}",
                    d1s[i], d2s[i]
                ));
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
